        cwd: request.root,
        env: hasInvocationKey
          ? { ...workerEnvironment, LATTICE_MANAGED_HOST_WORKER_CAPABILITY_FD: '3' }
          : workerEnvironment,
        detached: true,
        stdio: hasInvocationKey ? ['ignore', logFd, logFd, 'pipe'] : ['ignore', logFd, logFd],
      },
