      if (child.pid) {
        try { process.kill(-child.pid, 'SIGKILL'); } catch {
          try { child.kill('SIGKILL'); } catch { /* fail closed below */ }
        }
      } else {
        try { child.kill('SIGKILL'); } catch { /* spawn may already have failed */ }
      }
      await Promise.race([
        new Promise<void>(resolveClose => {
          if (child.exitCode !== null || child.signalCode !== null) resolveClose();
          else {
            child.once('close', () => resolveClose());
            child.once('error', () => resolveClose());
          }
        }),
        sleep(1_000),
      ]);
    };
